@import url('https://fonts.googleapis.com/css2?family=Vazirmatn:wght@400;500;700;800&display=swap');*{box-sizing:border-box}body{margin:0;background:#071225;color:#f7f8fb;font-family:Vazirmatn,Arial,sans-serif}.nav{height:72px;border-bottom:1px solid #23314b;display:flex;align-items:center;justify-content:space-between;padding:0 5%;position:relative;z-index:2}.brand{font-size:22px;font-weight:800}.brand span{color:#e32645}.links{display:flex;gap:30px;color:#b9c4d8;font-size:14px}.login,.primary{background:#d51e3e;color:white;border:0;border-radius:14px;padding:12px 22px;font:inherit;cursor:pointer}.hero{min-height:520px;padding:80px 7%;display:flex;align-items:center;background:linear-gradient(90deg,#071225 5%,rgba(7,18,37,.82) 43%,rgba(7,18,37,.15)),url('/images/concepts/home-concept.png') center/cover}.hero h1{font-size:48px;max-width:540px;line-height:1.35;margin:0 0 20px}.hero p{color:#c4cedd;max-width:500px;line-height:2}.actions{display:flex;gap:12px;margin-top:28px}.secondary{border:1px solid #6c7890;color:#fff;background:transparent;border-radius:14px;padding:11px 22px;font:inherit}.search{margin:-35px auto 0;position:relative;width:86%;background:#12243d;border:1px solid #2d405f;border-radius:18px;padding:18px;display:grid;grid-template-columns:1fr 1fr 1fr 150px;gap:12px}.field{background:#0b1930;border:1px solid #314460;border-radius:12px;padding:14px;color:#cad3e1}.section{padding:48px 7%}.section h2{font-size:25px}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px}.card{background:#10213a;border:1px solid #263a58;border-radius:16px;overflow:hidden}.poster{height:220px;background:linear-gradient(160deg,#8c2034,#182c4b);display:flex;align-items:end;padding:16px;font-size:18px;font-weight:700}.cardbody{padding:14px;color:#aebbd0;font-size:13px}.venues{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.venue{padding:24px;background:#10213a;border:1px solid #263a58;border-radius:16px}.muted{color:#8fa0ba}@media(max-width:900px){.links{display:none}.hero h1{font-size:35px}.search,.grid,.venues{grid-template-columns:1fr 1fr}.search{margin:20px auto}.grid .card:last-child{display:none}}@media(max-width:560px){.search,.grid,.venues{grid-template-columns:1fr}.hero{padding:50px 6%}}
</style></head><body><header class="nav"><div class="brand">سینما<span>پلاس</span></div><nav class="links"><a>فیلم‌ها</a><a>تئاترها</a><a>سینماها</a><a>اخبار و مقالات</a></nav><button class="login">ورود / ثبت‌نام</button></header><main><section class="hero"><div><div class="muted">تجربه‌ای فراتر از تماشا</div><h1>لحظه‌های خوب، روی پرده بزرگ منتظر شماست</h1><p>فیلم‌ها و نمایش‌های محبوب را پیدا کنید، بهترین صندلی را انتخاب کنید و با خیال راحت بلیت بخرید.</p><div class="actions"><button class="primary">خرید بلیت</button><button class="secondary">مشاهده برنامه‌ها</button></div></div></section><div class="search"><div class="field">همه آثار ▾</div><div class="field">در کدام شهر؟ تهران ▾</div><div class="field">در چه تاریخی؟ انتخاب تاریخ ▾</div><button class="primary">جست‌وجو</button></div><section class="section"><h2>فیلم‌ها و نمایش‌های منتخب</h2><div class="grid">@foreach($events as $event)<article class="card"><div class="poster">{{ $event->title }}</div><div class="cardbody">{{ $event->category?->name }} <span class="muted"> · {{ $event->duration }} دقیقه</span><p>{{ $event->summary }}</p></div></article>@endforeach</div></section><section class="section"><h2>سینماها و تالارهای منتخب</h2><div class="venues">@foreach($venues as $venue)<div class="venue"><h3>{{ $venue->name }}</h3><div class="muted">{{ $venue->city }} · {{ $venue->address }}</div><p>{{ number_format($venue->capacity) }} صندلی</p></div>@endforeach</div></section></main></body></html>
